def compute(vars):
    value_2019 = vars["v1"]
    value_2018 = vars["v2"]

    if value_2019 > value_2018:
        result = "2019"
    elif value_2018 > value_2019:
        result = "2018"
    else:
        result = None

    return {
        "value": result,
        "trace": {
            "value_2019": value_2019,
            "value_2018": value_2018,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
